saved def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 4]
    if not cells:
        return out
    top = min(r for r, c in cells)
    bottom = max(r for r, c in cells)
    height = bottom - top + 1
    for r, row in enumerate(out):
        for c, value in enumerate(row):
            if value == 6:
                out[r][c] = 0
    for r, c in cells:
        reflected_r = 2 * top + 2 * height - 1 - r
        if reflected_r < len(out):
            out[reflected_r][c] = 4
    return out
